import { DAY,day,percent,normalize,validateSnapshot,parseJSON,matches,summarize,previousWindow,diagnosis,trend } from './model.mjs';
import { taxonomy as projectTaxonomy } from './taxonomy.mjs';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',trend:'M3 17l6-6 4 3 8-10 M15 4h6v6 M3 21h18',target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9 M17 3h4v4',book:'M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1z M12 5v15',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',shield:'M12 2l8 3v7c0 5-8 10-8 10S4 17 4 12V5z M8 12l3 3 5-6',database:'M20 5c0 2-16 2-16 0s16-2 16 0z M4 5v14c0 3 16 3 16 0V5 M4 12c0 3 16 3 16 0',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',arrow:'M5 12h14 M13 6l6 6-6 6',close:'M6 6l12 12 M18 6L6 18',menu:'M4 6h16 M4 12h16 M4 18h16',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',edit:'M14 4l6 6 M4 20l1-6L17 2l5 5L10 19z',message:'M4 3h16v14H9l-5 4z M8 8h8 M8 12h5',info:'M12 8v.1 M12 11v6 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const names={overview:'能力概览',trends:'成长趋势',priorities:'重点关注',materials:'学习资料',report:'Learning reports'};
const moduleNames={grammar:'语法纠错',review:'词汇复习',practice:'中文转英文',vocabulary:'Saved words',ask:'Ask notes',coach:'Coach reports',text:'文本分析',unclassified:'来源未分类','practice-log':'Practice Markdown','practice-choice':'选择练习','practice-word':'单词练习','practice-expression':'表达练习'};
const kindNames={grammar:'Grammar corrections',review:'词汇复习',practice:'练习记录',word:'Saved words',note:'Ask notes',report:'Coach reports','practice-log':'Practice Markdown'};
const statusNames={'new':'New · 尚未复习','learning':'Learning · 学习中','needs-reinforcement':'Needs reinforcement','retained':'Retained · 已保留','well-retained':'Well retained · 较稳固','insufficient-history':'历史证据不足','unavailable':'状态不可用'};
const statusColors={'new':'#b8c3d0','learning':'#3d9ed1','needs-reinforcement':'#d69c3d','retained':'#54ba7a','well-retained':'#247446','insufficient-history':'#8d98a6','unavailable':'#aeb6bf'};
let snapshot=null,records=[],taxonomy=projectTaxonomy,view=names[location.hash.slice(1)] ? location.hash.slice(1) : 'overview';
let filtered=[],summary,previousSummary,previousRows=[], materialTab='all',page=0,metric='recall',compareMode='time',typeA='Verb Tense',typeB='Article Usage',moduleA='grammar',moduleB='practice';
const today=day(Date.now()),filters={start:day(Date.now()-29*DAY),end:today,module:'all',category:'all',errorType:'all',status:'all',search:'',includeUndated:false};
const timeLabel=value=>Number.isFinite(value)?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(value):'日期未知';
const dateLabel=r=>Number.isFinite(r.date)?day(r.date):'日期未知';
const notice=message=>{ $('#notice').textContent=message;$('#notice').hidden=!message; };
function wireIcons(){ $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));$('#mobile-menu').innerHTML=icon('menu');$('#close-detail').innerHTML=icon('close');$('#close-data').innerHTML=icon('close'); }
function updateTypeOptions(){const types=filters.category==='all'?Object.values(taxonomy).flat():taxonomy[filters.category];$('#errorType').innerHTML='<option value="all">全部具体类型</option>'+types.map(t=>`<option ${t===filters.errorType?'selected':''}>${esc(t)}</option>`).join('');}
function syncFilters(){for(const id of ['start','end','module','category'])$('#'+id).value=filters[id];updateTypeOptions();}
function currentRows(extra={}){return records.filter(r=>matches(r,{...filters,...extra},taxonomy));}
function calculate(){filtered=currentRows();summary=summarize(filtered,taxonomy);const previous=previousWindow(filters.start,filters.end);previousRows=currentRows(previous);previousSummary=summarize(previousRows,taxonomy);}
const empty=(text='当前筛选范围没有记录',detail='可扩大时间范围，或调整模块和错误类型。')=>`<div class="empty">${esc(text)}${detail?`<p>${esc(detail)}</p>`:''}</div>`;
const section=(title,subtitle='',action='')=>`<div class="section-heading"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>`;
const goto=(name,label)=>`<button class="text-button" data-goto="${name}">${label}${icon('arrow')}</button>`;
function delta(current,previous,suffix='个百分点') { if(!$('#compare').checked || current===null || previous===null)return '';const d=current-previous;return `<span class="delta ${d<0?'down':''}">${d>0?'+':''}${d.toFixed(suffix==='条'?0:1)} ${suffix}</span>`; }
function savedCards(){return section('你的学习资料','表达、词汇与思考，积累在一起。',goto('materials','浏览全部'))+`<div class="saved-grid">${[['word','book','Saved words'],['grammar','edit','Grammar corrections'],['note','message','Ask notes'],['report','file','Coach reports']].map(([kind,ic,label])=>`<button class="saved-card" data-tab="${kind}"><span class="saved-card-top">${icon(ic)}${icon('arrow','tiny-arrow')}</span><strong>${label}</strong><div><span class="count">${filtered.filter(r=>r.kind===kind).length}</span><small>条 · 当前筛选</small></div></button>`).join('')}</div>`;}
function metrics(){const retained=summary.words.filter(w=>['retained','well-retained'].includes(w.status)).length;return `<div class="metrics"><div class="metric"><div class="metric-label">无提示词汇回忆正确率</div><strong>${percent(summary.independentRecall)}</strong>${delta(summary.independentRecall,previousSummary.independentRecall)}<p>${summary.unaided.filter(r=>r.correct).length} / ${summary.unaided.length} 次 · 未播放音频</p></div><div class="metric"><div class="metric-label">中文转英文 · 平均得分</div><strong>${summary.practiceScore===null?'—':summary.practiceScore.toFixed(1)}</strong>${delta(summary.practiceScore,previousSummary.practiceScore,'分')}<p>${summary.practice.length} 次已评分翻译 · 满分 100</p></div><div class="metric"><div class="metric-label">有已保存诊断的纠错记录</div><strong>${summary.affected}<span class="muted" style="font-size:15px"> / ${summary.grammar.length}</span></strong>${delta(summary.affected,previousSummary.affected,'条')}<p>记录数 · 不等于实际错误率</p></div><div class="metric"><div class="metric-label">词汇保留 · 当前状态</div><strong>${retained}<span class="muted" style="font-size:15px"> / ${summary.words.length}</span></strong><p>Retained + Well retained · 所选词条</p></div></div>`;}
const metricNames={recall:'无提示回忆正确率',score:'翻译平均得分',errors:'有已保存诊断的记录占比'};
function chart(points,previous){const valid=points.filter(p=>p.value!==null);if(!valid.length && !previous.some(p=>p.value!==null))return `<div class="chart-empty">当前范围没有可绘制的${esc(metricNames[metric])}<small>缺失观测留空，不补成 0。</small></div>`;
  const w=620,h=220,left=34,right=12,top=13,bottom=27,step=(w-left-right)/Math.max(points.length-1,1), x=i=>left+(points.length===1?(w-left-right)/2:i*step),y=v=>top+(100-v)/100*(h-top-bottom);
  const series=(rows,color,dashed=false)=>{let path='',open=false;rows.forEach((p,i)=>{if(p.value===null){open=false;return;}path+=`${open?'L':'M'}${x(i)},${y(p.value)} `;open=true;});return `<path d="${path}" fill="none" stroke="${color}" stroke-width="2.5" ${dashed?'stroke-dasharray="5 5"':''}/>`+rows.map((p,i)=>p.value===null?'':`<circle cx="${x(i)}" cy="${y(p.value)}" r="3.5" fill="${color}" tabindex="0" role="button" data-point="${i}" data-series="${dashed?'previous':'current'}" aria-label="${p.start} 至 ${p.end}，${p.value.toFixed(1)}，${p.denominator} 次记录"><title>${p.start} — ${p.end} · ${p.value.toFixed(1)} · n=${p.denominator}</title></circle>`).join('');};
  return `<svg viewBox="0 0 ${w} ${h}" class="chart" role="img" aria-label="${metricNames[metric]}趋势，点击观测点查看记录">${[0,25,50,75,100].map(v=>`<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#edf1f5" stroke-dasharray="3 4"/><text x="${left-9}" y="${y(v)+4}" text-anchor="end">${v}</text>`).join('')}${$('#compare').checked?series(previous,'#a4afb9',true):''}${series(points,'#2fbe63')}${points.map((p,i)=>i===0||i===points.length-1||i%Math.max(1,Math.ceil(points.length/5))===0?`<text x="${x(i)}" y="${h-4}" text-anchor="middle">${p.start.slice(5).replace('-','/')}</text>`:'').join('')}</svg>`;
}
function trendPanel(){const p=trend(filtered,filters.start,filters.end,metric),prev=previousWindow(filters.start,filters.end),q=trend(previousRows,prev.start,prev.end,metric);return `<section class="panel"><div class="panel-title"><div><h2>表现如何变化</h2><p>基于已记录的表现，按时间聚合</p></div><select id="metric" aria-label="趋势指标">${Object.entries(metricNames).map(([k,v])=>`<option value="${k}" ${metric===k?'selected':''}>${v}</option>`).join('')}</select></div>${chart(p,q)}<div class="legend"><span><i></i>当前时段</span>${$('#compare').checked?'<span><i class="previous"></i>上一等长时段</span>':''}</div><details><summary>查看数据与分母</summary><div class="table-wrap"><table><thead><tr><th>时段</th><th>当前值</th><th>记录 n</th>${$('#compare').checked?'<th>对比值 / n</th>':''}</tr></thead><tbody>${p.map((r,i)=>`<tr><td><button data-point="${i}" data-series="current">${r.start}—${r.end}</button></td><td>${r.value===null?'—':r.value.toFixed(1)+(metric==='score'?'':'%')}</td><td>${r.denominator}</td>${$('#compare').checked?`<td>${q[i]?.value==null?'—':q[i].value.toFixed(1)} / ${q[i]?.denominator||0}</td>`:''}</tr>`).join('')}</tbody></table></div></details><p class="panel-note">${metric==='recall'?'仅计 correct 已记录且 audioPlayed=false 的回忆。':metric==='score'?'整体翻译评分含提示与重试，不代表某条规则已掌握。':'基于保存的模型诊断，缺少诊断不代表语言使用正确。'} 观测点可下钻。</p></section>`;}
function distribution(){const max=Math.max(...summary.categories.map(x=>x.count),1);return `<section class="panel"><div class="panel-title"><div><h2>错误分布</h2><p>保存的模型诊断 · 按涉及记录去重</p></div><span class="tag">n = ${summary.grammar.length}</span></div><div class="bar-list">${summary.categories.map((r,i)=>`<button class="bar-row" data-category="${r.category}" aria-label="筛选 ${r.category}，${r.count} 条记录"><span class="bar-label">${r.category}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${r.count/max*100}%;background:${['#2fbe63','#55a4c6','#d8a34f','#9c8dc3','#7595ab'][i]}"></span></span><span class="bar-number">${r.count}</span></button>`).join('')}</div><p class="panel-note">同一记录可涉及多个大类，不能相加视为唯一记录数。点击分类查看原始证据。</p></section>`;}
function retention(){const statuses=Object.keys(statusNames),total=summary.words.length;return `<section class="panel"><div class="panel-title"><div><h2>词汇保留状态</h2><p>沿用现有 Review history 证据规则</p></div><span class="tag">当前快照</span></div><div class="status-stack">${statuses.map(s=>`<span style="background:${statusColors[s]};width:${total?summary.words.filter(w=>w.status===s).length/total*100:0}%" title="${statusNames[s]}"></span>`).join('')}</div><div class="status-legend">${statuses.map(s=>{const n=summary.words.filter(w=>w.status===s).length;return n||s!=='unavailable'?`<button data-status="${s}"><i class="dot" style="background:${statusColors[s]}"></i>${esc(statusNames[s])}<b>${n}</b></button>`:'';}).join('')}</div><p class="panel-note">状态由真实回忆、提示使用和时间跨度决定。排期间隔与 streak 不作为掌握证据；不重建未记录的历史状态。</p></section>`;}
function diagnosisPanel(){return `<section class="panel diagnosis-panel"><h2 class="diagnosis-title">${icon('spark')}给当前的你，一点观察</h2><p>${esc(diagnosis(summary))}</p><div class="panel-note">仅指出突出问题与改进方向，不生成学习计划。</div><button class="text-button" data-goto="report">查看诊断报告 ${icon('arrow')}</button></section>`;}
function priorityPanel(full=false){const list=summary.counts.slice(0,full?28:3);return `<section class="panel"><div class="panel-title"><div><h2>${full?'具体 error types':'最值得关注的 3 个问题'}</h2><p>按涉及记录数排序 · 查看证据后再判断</p></div>${!full?goto('priorities','展开'):''}</div>${!list.length?empty('没有可排序的具体类型','未知标签保留在原始记录中，不强行归类。'):`<div class="priority-list">${list.map((r,i)=>`<div class="priority"><span class="rank">${i+1}</span><div><div class="priority-title">${esc(r.type)}</div><div class="priority-desc">${r.category} · ${r.count} 条记录 · ${r.distinct} 个不同输入 <span class="tag ${r.distinct>=2?'amber':''}">${r.distinct>=2?'多输入中出现':'单次观察'}</span></div></div><button class="evidence-button" data-error="${esc(r.type)}">看例句 ${icon('arrow')}</button></div>`).join('')}</div>`}<div class="mastery-note">${icon('info')}规则掌握度：证据不足。现有纠错与整体练习分数无法证明长期、独立、跨语境掌握。</div></section>`;}
function activityPanel(all=false){const rows=filtered.filter(r=>r.kind!=='practice-log').slice(0,all?100:6);return `<section class="panel"><div class="panel-title"><div><h2>最近活动</h2><p>回到那一次真实的表达与回忆</p></div>${all?'':goto('materials','查看全部')}</div>${!rows.length?empty():`<div class="recent-list">${rows.map(r=>`<button class="activity" data-record="${esc(r.key)}"><span class="activity-icon">${icon(r.kind==='word'?'book':r.kind==='note'?'message':r.kind==='review'?'clock':r.kind==='report'?'file':'edit')}</span><span style="min-width:0"><span class="activity-title">${esc(r.title)}</span><small>${esc(moduleNames[r.module]||r.module)}${r.kind==='review'?' · '+(r.correct===true?'回忆正确':r.correct===false?'需要巩固':'结果未知'):''}</small></span><time>${Number.isFinite(r.date)?day(r.date).slice(5).replace('-','/'):'未知'}</time></button>`).join('')}</div>`}</section>`;}
function comparePanel(){const previous=previousWindow(filters.start,filters.end);let body='';if(compareMode==='time'){body=`<p class="panel-note">当前 ${filters.start} — ${filters.end}；对比 ${previous.start} — ${previous.end}。相同筛选条件、相同天数。</p><div class="table-wrap"><table><thead><tr><th>指标</th><th>当前</th><th>上一时段</th><th>差值</th></tr></thead><tbody>${[['无提示回忆正确率',percent(summary.independentRecall),percent(previousSummary.independentRecall),summary.independentRecall,previousSummary.independentRecall,'pp'],['翻译平均得分',summary.practiceScore?.toFixed(1)??'—',previousSummary.practiceScore?.toFixed(1)??'—',summary.practiceScore,previousSummary.practiceScore,'分'],['涉及诊断的纠错记录',`${summary.affected}/${summary.grammar.length}`,`${previousSummary.affected}/${previousSummary.grammar.length}`,summary.affected,previousSummary.affected,'条']].map(([label,a,b,av,bv,unit])=>`<tr><td>${label}</td><td>${a}</td><td>${b}</td><td>${av===null||bv===null?'—':(av-bv).toFixed(1)+' '+unit}</td></tr>`).join('')}</tbody></table></div>`;}
 else if(compareMode==='module'){const opts=val=>Object.entries(moduleNames).map(([k,n])=>`<option value="${k}" ${val===k?'selected':''}>${n}</option>`).join('');const a=summarize(records.filter(r=>matches(r,filters,taxonomy,{ignoreModule:true})&&r.module===moduleA),taxonomy),b=summarize(records.filter(r=>matches(r,filters,taxonomy,{ignoreModule:true})&&r.module===moduleB),taxonomy);body=`<div class="compare-controls"><label>模块 A<select id="module-a">${opts(moduleA)}</select></label><span class="compare-vs">对比</span><label>模块 B<select id="module-b">${opts(moduleB)}</select></label></div><div class="table-wrap"><table><thead><tr><th>各模块可支持的指标</th><th>${moduleNames[moduleA]}</th><th>${moduleNames[moduleB]}</th></tr></thead><tbody><tr><td>语法检查 n</td><td>${a.grammar.length}</td><td>${b.grammar.length}</td></tr><tr><td>翻译得分 / n</td><td>${a.practiceScore?.toFixed(1)??'—'} / ${a.practice.length}</td><td>${b.practiceScore?.toFixed(1)??'—'} / ${b.practice.length}</td></tr><tr><td>无提示回忆正确率 / n</td><td>${percent(a.independentRecall)} / ${a.unaided.length}</td><td>${percent(b.independentRecall)} / ${b.unaided.length}</td></tr></tbody></table></div><p class="panel-note">模块对比覆盖上方模块选择；日期与分类等筛选保留。各模块的分数定义不同，不合成综合能力分。</p>`;}
 else {const opts=val=>Object.values(taxonomy).flat().map(t=>`<option ${val===t?'selected':''}>${esc(t)}</option>`).join('');const base=currentRows({category:'all',errorType:'all'}).filter(r=>r.kind==='grammar' && r.module==='grammar' && r.raw.formatSupported!==false);body=`<div class="compare-controls"><label>类型 A<select id="type-a">${opts(typeA)}</select></label><span class="compare-vs">对比</span><label>类型 B<select id="type-b">${opts(typeB)}</select></label></div><div class="table-wrap"><table><thead><tr><th>具体类型</th><th>涉及记录 / 检查 n</th><th>占比</th><th>不同输入</th></tr></thead><tbody>${[typeA,typeB].map(t=>{const rows=base.filter(r=>r.types.includes(t));return `<tr><td><button data-error="${esc(t)}">${esc(t)}</button></td><td>${rows.length} / ${base.length}</td><td>${percent(base.length?rows.length/base.length*100:null)}</td><td>${new Set(rows.map(r=>r.original?.trim().replace(/\s+/g,' ').toLowerCase())).size}</td></tr>`;}).join('')}</tbody></table></div><p class="panel-note">类型对比覆盖上方分类与具体类型选择；保留日期、模块与搜索范围。占比仅指保存的诊断，不代表错误发生概率。</p>`;}
 return `<section class="panel" style="margin-top:20px"><div class="panel-title"><div><h2>换一个角度，看变化</h2><p>相同口径下比较，差异才有意义。</p></div></div><div class="tabs" style="margin-bottom:19px">${[['time','不同时段'],['module','不同模块'],['type','不同错误类型']].map(([k,n])=>`<button data-compare-mode="${k}" class="${compareMode===k?'active':''}">${n}</button>`).join('')}</div>${body}</section>`;}
function materials(){let rows=filtered.filter(r=>materialTab==='all' || r.kind===materialTab);const limit=18,total=rows.length;page=Math.min(page,Math.max(0,Math.ceil(total/limit)-1));const pageRows=rows.slice(page*limit,(page+1)*limit);return `<div class="material-toolbar"><div class="tabs">${[['all','全部'],['word','Saved words'],['grammar','Corrections'],['note','Ask notes'],['report','Reports'],['review','复习'],['practice','练习'],['practice-log','Markdown 记录']].map(([k,n])=>`<button data-material-tab="${k}" class="${materialTab===k?'active':''}">${n}</button>`).join('')}</div><input class="search" id="search" type="search" placeholder="搜索原句、单词或笔记…" aria-label="搜索记录" value="${esc(filters.search)}"></div><div class="material-toolbar"><label class="muted small-text">保留状态 <select id="status"><option value="all">全部状态</option>${Object.entries(statusNames).map(([k,n])=>`<option value="${k}" ${filters.status===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="check-line" style="margin:0"><input type="checkbox" id="undated" ${filters.includeUndated?'checked':''}>包括日期未知的资料</label><span class="muted small-text">${total} 条资料与记录</span></div>${!total?empty():`<div class="materials-grid">${pageRows.map(r=>`<button class="panel material" data-record="${esc(r.key)}"><span class="tag ${r.kind==='word'?'green':''}" style="align-self:flex-start">${esc(kindNames[r.kind]||r.kind)}</span><h3>${esc(r.title)}</h3><p>${esc(r.kind==='word'?(r.raw.zh||r.raw.meaning):r.correction||r.content||r.original)}</p><div class="material-meta"><small>${dateLabel(r)}${r.kind==='word'?' · '+(statusNames[r.status]||r.status):''}</small>${icon('arrow')}</div></button>`).join('')}</div><div class="pagination"><button id="materials-prev" class="secondary small" data-page="${page-1}" ${page===0?'disabled':''}>上一页</button><span>${page+1} / ${Math.ceil(total/limit)}</span><button id="materials-next" class="secondary small" data-page="${page+1}" ${(page+1)*limit>=total?'disabled':''}>下一页</button></div>`}`;}
function reportMarkup(){return `<div class="report-actions"><button class="primary" id="download-md">${icon('download')}下载 Markdown</button><button class="secondary" id="print-report">${icon('file')}打印 / 保存 PDF</button></div><article class="panel report-page"><div class="report-cover"><h2>English skills report</h2><p>个性化英语能力诊断 · ${filters.start} — ${filters.end}</p><p>模块：${esc(moduleNames[filters.module]||'全部')} · 分类：${esc(filters.category)} · Error type：${esc(filters.errorType)}</p><p>快照：${esc(snapshot?.exportedAt||'未导入')} · 统计口径：已保存记录</p></div><section class="report-section"><h3>目前最突出的观察</h3><p>${esc(diagnosis(summary))}</p></section><section class="report-section"><h3>证据支持的表现</h3><div class="report-stats"><div><small>无提示回忆正确率 / ${summary.unaided.length} 次</small><b>${percent(summary.independentRecall)}</b></div><div><small>翻译平均得分 / ${summary.practice.length} 次</small><b>${summary.practiceScore?.toFixed(1)??'—'}</b></div><div><small>纠错记录 / 保存诊断涉及记录</small><b>${summary.grammar.length} / ${summary.affected}</b></div></div><p>词汇回忆仅统计明确记录的 correct 与音频提示；翻译得分为整体评分，可能含重试与提示。</p></section><section class="report-section"><h3>具体错误类型与证据</h3>${summary.counts.length?`<div class="table-wrap"><table><thead><tr><th>Error type</th><th>涉及记录</th><th>不同输入</th><th>证据</th></tr></thead><tbody>${summary.counts.map(r=>`<tr><td>${esc(r.type)}</td><td>${r.count}</td><td>${r.distinct}</td><td><button data-error="${esc(r.type)}">查看例句</button></td></tr>`).join('')}</tbody></table></div>`:empty('没有具体错误类型证据','')}</section><section class="report-section"><h3>词汇保留与掌握证据</h3><p>所选词条 ${summary.words.length} 个；Retained ${summary.words.filter(w=>w.status==='retained').length} 个，Well retained ${summary.words.filter(w=>w.status==='well-retained').length} 个。这是当前快照的状态，不是历史时间点状态。规则掌握度证据不足，不生成百分比或等级。</p></section><section class="report-section"><h3>证据边界</h3><p>保存的模型诊断、修正及参考答案可能有误。没有诊断不能证明正确；已保存记录不能代表全部使用情况。同一句的重试不能证明跨语境进步。当前报告仅描述纠错、词汇回忆和中文转英文记录支持的表现。</p><p>${esc(snapshot?.coverage.filter(c=>c.status!=='available').map(c=>`${c.source}：${c.status}`).join('；')||'已导入的数据源读取正常。')} 所有统计均遵循当前筛选条件；资料条数与能力证据分开统计。</p></section><details class="report-section"><summary>查看报告引用的原始纠错记录（${summary.grammar.length}）</summary>${summary.grammar.map(r=>`<div class="history-row"><button class="evidence-button" data-record="${esc(r.key)}">${esc(r.original)}</button><small>${esc(r.key)} · ${dateLabel(r)}</small></div>`).join('')}</details></article>`;}
function focusLocator(element) {
  if (!element || !$('#workspace').contains(element)) return null;
  if (element.id) return '#'+CSS.escape(element.id);
  for (const name of ['data-material-tab','data-compare-mode','data-page','data-point']) {
    if (element.hasAttribute(name)) return '['+name+'="'+CSS.escape(element.getAttribute(name))+'"]';
  }
  return null;
}
function updateNavigation() {
  const sidebar=$('.sidebar'),mobile=matchMedia('(max-width:680px)').matches;
  const hidden=mobile&&!sidebar.classList.contains('open');
  sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden));
  $('#mobile-menu').setAttribute('aria-controls','workspace-navigation');
  sidebar.id='workspace-navigation';
}
function render(){const restore=focusLocator(document.activeElement);calculate();$('#crumb').textContent=names[view];$('#page-title').textContent={overview:'看见进步，也看清下一步。',trends:'让变化，有证据可循。',priorities:'从反复出现的地方，理解自己。',materials:'让每一次学习，都有处可寻。',report:'属于你的英语能力观察。'}[view];$('#page-subtitle').textContent={overview:'从真实的表达与回忆中，发现你的英语成长。',trends:'对比时段、模块与错误类型，回到表现背后的记录。',priorities:'频次只是线索。原始例句，才是判断的起点。',materials:'在同一处查看单词、纠错、笔记、报告和练习历史。',report:'只呈现现有证据能够支持的表现与改进方向。'}[view];$$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#empty-onboarding').hidden=Boolean(snapshot);$('#filter-count').textContent=`${filtered.length} 条匹配记录`;$('#sync-label').textContent=snapshot?`快照 ${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(snapshot.exportedAt))}`:'等待导入';$('#workspace').innerHTML=view==='overview'?savedCards()+metrics()+`<div class="analysis-grid">${trendPanel()}${distribution()}</div><div class="bottom-grid">${retention()}${diagnosisPanel()}</div>${section('把观察带回学习','从高频问题出发，回到原始记录。')}<div class="bottom-grid" style="margin-top:0">${priorityPanel()}${activityPanel()}</div>`:view==='trends'?metrics()+`<div class="analysis-grid">${trendPanel()}${distribution()}</div>`+comparePanel():view==='priorities'?`<div class="analysis-grid">${priorityPanel(true)}${diagnosisPanel()}</div>`+comparePanel():view==='materials'?materials():reportMarkup();
  $('#workspace').querySelectorAll('button:disabled').forEach(b=>b.style.cursor='default');
  if(restore){const candidate=$('#workspace').querySelector(restore);const target=candidate&&!candidate.disabled?candidate:$('#workspace').querySelector('.pagination button:not(:disabled), #search');target?.focus({preventScroll:true});}
  updateNavigation();
}
function navigate(next){if(!names[next])return;view=next;location.hash=next;page=0;$('.sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');render();$('#page-title').setAttribute('tabindex','-1');$('#page-title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function openDetail(html,label){$('#detail-kind').textContent=label;$('#detail-body').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
const field=(label,value,corrected=false)=>value!==null&&value!==undefined&&value!==''?`<section class="field ${corrected?'corrected':''}"><h3>${esc(label)}</h3><div class="field-content">${esc(value)}</div></section>`:'';
function markdown(text){return String(text||'').split(/\n\s*\n/).map(block=>{const m=block.match(/^(#{1,6}) (.*)/);if(m)return `<h3>${esc(m[2])}</h3>`;if(/^```/.test(block))return `<pre>${esc(block.replace(/^```[^\n]*\n?/,'').replace(/```$/,''))}</pre>`;return `<p>${esc(block)}</p>`;}).join('');}
function openRecord(key){const r=records.find(r=>r.key===key);if(!r)return;let content=`<h2 id="detail-title">${esc(r.title)}</h2><p class="record-meta">${esc(moduleNames[r.module]||r.module)} · ${timeLabel(r.date)}<br>${esc(r.key)}</p>`;
  if(r.kind==='word'){const w=r.raw;content+=`<span class="tag green">${esc(statusNames[w.learningStatus]||w.learningStatus)}</span>`+field('Meaning',w.meaning)+field('中文释义',w.zh)+field('词性与发音',[w.pos,w.phonetic].filter(Boolean).join(' · '))+field('Collocations',w.collocations)+field(w.plural?'Plural':'Verb forms',w.plural||w.verbForms)+field('例句',[w.example,w.example2,w.example3].filter(Boolean).join('\n\n'))+field('笔记',w.note);const history=records.filter(x=>x.kind==='review'&&w.srs&&x.cardId===w.srs.id);content+=`<section class="field"><h3>Word status · Review history（${history.length}）</h3><p class="panel-note">同一词条的全部已记录复习，不受概览时间筛选影响。历史默认收起。</p>${history.length?history.map(x=>`<details class="history-row"><summary>${timeLabel(x.date)} · ${x.correct===true?'正确':x.correct===false?'未回忆出':'未知'} · ${esc(x.feedback.rating||'未评分')}</summary>${field('你的回忆',x.original)}${field('参考答案',x.correction,true)}${field('音频提示',x.feedback.audioPlayed===true?'已使用':x.feedback.audioPlayed===false?'未使用':'未记录')}${field('复习后间隔',x.feedback.result?.next?.intervalDays===undefined?'未记录':`${x.feedback.result.next.intervalDays} 天`)}<p class="panel-note">复习前间隔未记录，不推断变化量。</p><button class="evidence-button" data-record="${esc(x.key)}">查看完整复习记录</button></details>`).join(''):empty('没有可关联的复习历史','')}</section>`;}
  else if(r.kind==='grammar'){content+=field('原始表达',r.original)+field('Correction · 保存的修正',r.correction,true)+field('More natural · 可选润色',r.raw.refine)+`<section class="field"><h3>保存的诊断（模型反馈，未经独立核验）</h3>${(r.raw.diagnoses||[]).map(d=>`<div class="diagnosis-item"><span class="tag">${esc(d.severity)}</span><strong>${esc(d.error_type)}</strong>${esc(d.evidence||'')}<p>${esc(d.explanation)}</p>${d.suggestion?`<p>Suggestion: ${esc(d.suggestion)}</p>`:''}</div>`).join('')||'<p class="panel-note">没有已保存的诊断；不据此推断完全正确。</p>'}</section>`+field('Remember',r.raw.remember);}
  else if(['practice','review','practice-log'].includes(r.kind)){content+=field(r.kind==='review'?'回忆提示':'中文提示 / 原题',r.prompt)+field('你的回答',r.original)+field('保存的修正 / 参考答案',r.correction,true);if(r.feedback){content+=field('反馈',r.feedback.feedback_zh||r.feedback.feedback||r.feedback.explanation)+field('整体得分',r.score)+field('提示使用',r.kind==='review'?(r.feedback.audioPlayed===true?'已播放音频':r.feedback.audioPlayed===false?'未播放音频':'未记录'):(r.hints===undefined?'未记录':`${r.hints}/3`))+field('复习评分',r.feedback.rating)+field('复习后间隔',r.feedback.result?.next?.intervalDays===undefined?null:`${r.feedback.result.next.intervalDays} 天`);}if(r.kind==='practice-log')content+=field('Markdown 原始反馈',r.content);if(r.targets?.length)content+=field('练习目标（不是错误判定）',r.targets.join(' · '));}
  else content+=`<div class="markdown">${markdown(r.content)}</div>`;
  const linked=snapshot?.notes.filter(n=>{const text=n.content||'';return text.includes(r.raw.entryId||r.key)||text.includes(r.key)||(r.kind==='word'&&new RegExp(`\\b${r.raw.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`,'i').test(text));})||[];
  if(linked.length&&r.kind!=='note')content+=`<section class="field"><h3>记录中可关联的已保存笔记</h3>${linked.map(n=>`<button class="activity" data-record="note:${esc(n.id)}">${esc(n.id.replace(/\.md$/i,''))}${icon('arrow')}</button>`).join('')}</section>`;
  if(r.kind==='report'&&Array.isArray(r.raw.evidence)){content+=`<section class="field"><h3>报告保存的证据（${r.raw.evidence.length}）</h3>${r.raw.evidence.map(e=>`<details class="history-row"><summary>${esc(e.entryId||e.id||e.label||'证据')}</summary><pre>${esc(JSON.stringify(e,null,2))}</pre>${e.entryId&&records.some(x=>x.raw.entryId===e.entryId)?`<button class="evidence-button" data-record="${esc(records.find(x=>x.raw.entryId===e.entryId).key)}">打开原始记录</button>`:''}</details>`).join('')}</section>`;}
  content+=`<details><summary>原始记录与字段</summary><pre>${esc(JSON.stringify(r.raw,null,2))}</pre></details>`;openDetail(content,kindNames[r.kind]||'记录详情');
}
function openEvidence(rows,title,note=''){openDetail(`<h2 id="detail-title">${esc(title)}</h2><p class="panel-note">${esc(note)}</p>${rows.length?rows.map(r=>`<button class="activity" data-record="${esc(r.key)}"><span class="activity-icon">${icon('file')}</span><span style="min-width:0"><span class="activity-title">${esc(r.title)}</span><small>${esc(moduleNames[r.module]||r.module)} · ${dateLabel(r)}</small></span>${icon('arrow')}</button>`).join(''):empty()}`,'证据下钻');}
function openError(type){const rows=currentRows({category:'all',errorType:'all'}).filter(r=>r.types.includes(type)||r.targets?.includes(type));openEvidence(rows,type,'纠错是已保存诊断；练习条目只表示目标机会，不证明该类型做对或做错。');}
function reportMarkdown(){const lines=['# English skills report','',`观察范围：${filters.start} — ${filters.end}`,`数据快照：${snapshot?.exportedAt||'未导入'}`,`筛选：${JSON.stringify(filters)}`,'','## 主要观察','',diagnosis(summary),'','## 证据支持的表现','',`- 无提示回忆正确率：${percent(summary.independentRecall)}（${summary.unaided.filter(r=>r.correct).length}/${summary.unaided.length} 次）`,`- 整体翻译平均分：${summary.practiceScore?.toFixed(1)??'—'}（${summary.practice.length} 次；含提示与可能重试）`,`- 已保存语法检查：${summary.grammar.length}；有保存诊断：${summary.affected}`,'','## 具体类型','', '| Error type | 涉及记录 | 不同输入 |','|---|---:|---:|',...summary.counts.map(r=>`| ${r.type} | ${r.count} | ${r.distinct} |`),'','## 当前词汇保留状态','',...Object.entries(statusNames).map(([s,n])=>`- ${n}：${summary.words.filter(w=>w.status===s).length}`),'','## 原始纠错证据','',...summary.grammar.flatMap(r=>[`### ${r.key} · ${dateLabel(r)}`,'',`原句：${r.original}`,'',`保存的修正：${r.correction||'未记录'}`,'',`保存的诊断：${r.types.join('；')||'无可识别的具体类型'}`,'']),'## 统计记录索引','',`词汇回忆：${summary.unaided.map(r=>r.key).join(', ')||'无'}`,`翻译：${summary.practice.map(r=>r.key).join(', ')||'无'}`,'','## 证据边界','','保存的模型诊断与修正未经独立核验；缺少诊断不代表正确。整体翻译分不能证明规则掌握。重试、提示与样本选择可能影响结果。保留状态是当前快照，不是历史状态。规则掌握度证据不足，不生成百分比或等级。','',...snapshot?.coverage.map(c=>`- ${c.source}: ${c.status} (${c.count??'—'})`)||[]];return lines.join('\n');}
function downloadReport(){if(!snapshot)return notice('请先导入项目数据，再导出诊断报告。');const blob=new Blob([reportMarkdown()],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ClearWrite-English-skills-${filters.end}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function storage(action,value){const db=await new Promise((resolve,reject)=>{const q=indexedDB.open('clearwrite-growth',1);q.onupgradeneeded=()=>q.result.createObjectStore('snapshots');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});try{return await new Promise((resolve,reject)=>{const tx=db.transaction('snapshots',action==='get'?'readonly':'readwrite'),store=tx.objectStore('snapshots'),q=action==='get'?store.get('current'):action==='put'?store.put(value,'current'):store.delete('current');let result;q.onsuccess=()=>result=q.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
function coverage(){ $('#coverage').innerHTML=snapshot?`<p class="muted small-text">导出时间 ${esc(snapshot.exportedAt)}</p>`+snapshot.coverage.map(c=>`<div class="coverage-row"><span>${esc(c.source)}</span><span class="tag ${c.status==='available'?'green':'amber'}">${c.status==='available'?`${c.count??'—'} 条 · 可用`:esc(c.status)}</span></div>`).join('')+'<p class="panel-note">Practice Markdown 与 SQLite 练习可能重叠，分别显示，统计不重复相加。日期未知的笔记可在资料页选择显示。</p>':'<p class="muted">尚未导入数据。</p>';}
async function adopt(data,{restored=false}={}){validateSnapshot(data);const normalized=normalize(data);taxonomy=data.taxonomy;snapshot=data;records=normalized;const latest=day(Date.parse(data.exportedAt));if(!restored){filters.end=latest;filters.start=day(Date.parse(data.exportedAt)-29*DAY);filters.module='all';filters.category='all';filters.errorType='all';filters.status='all';filters.search='';filters.includeUndated=false;$$('[data-period]').forEach(b=>b.classList.toggle('selected',b.dataset.period==='30'));}syncFilters();coverage();notice('');render();if($('#persist').checked)await storage('put',data);}
function openData(){coverage();$('#data-dialog').showModal();}
async function importFile(file){if(!file)return;if(file.size>40*1024*1024)return notice('文件超过 40 MB，请选择项目导出的学习数据快照。');try{await adopt(JSON.parse(await file.text()));if($('#data-dialog').open)$('#data-dialog').close();}catch(e){notice(`导入失败：${e.message} 当前记录保持不变。`);}finally{$('#file-input').value='';}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-goto],[data-tab],[data-material-tab],[data-page],[data-record],[data-error],[data-category],[data-status],[data-period],[data-compare-mode],[data-point]');if(!b)return;
 if(b.dataset.goto)navigate(b.dataset.goto);
 if(b.dataset.tab){materialTab=b.dataset.tab;navigate('materials');}
 if(b.dataset.materialTab){materialTab=b.dataset.materialTab;page=0;render();}
 if(b.dataset.page!==undefined){page=Number(b.dataset.page);render();}
 if(b.dataset.record)openRecord(b.dataset.record);
 if(b.dataset.error)openError(b.dataset.error);
 if(b.dataset.category){filters.category=b.dataset.category;filters.errorType='all';syncFilters();render();openEvidence(currentRows().filter(r=>r.kind==='grammar'),`${filters.category} · 原始记录`);}
 if(b.dataset.status){filters.status=b.dataset.status;materialTab='word';navigate('materials');}
 if(b.dataset.period){const period=b.dataset.period,anchor=snapshot?Date.parse(snapshot.exportedAt):Date.now();filters.end=day(anchor);const dates=records.filter(r=>Number.isFinite(r.date)).map(r=>r.date);filters.start=period==='all'?(dates.length?day(Math.min(...dates)):day(anchor)):day(anchor-(Number(period)-1)*DAY);filters.includeUndated=period==='all';$$('[data-period]').forEach(x=>x.classList.toggle('selected',x===b));syncFilters();page=0;render();}
 if(b.dataset.compareMode){compareMode=b.dataset.compareMode;render();}
 if(b.dataset.point!==undefined){const previous=b.dataset.series==='previous',f=previous?previousWindow(filters.start,filters.end):filters,rows=previous?previousRows:filtered,point=trend(rows,f.start,f.end,metric)[Number(b.dataset.point)];if(point)openEvidence(rows.filter(r=>day(r.date)>=point.start&&day(r.date)<=point.end&&(metric==='recall'?r.kind==='review'&&r.correct!==null&&r.feedback.audioPlayed===false:metric==='score'?r.module==='practice'&&r.kind==='practice':r.kind==='grammar'&&r.module==='grammar')),`${point.start} — ${point.end}`,metricNames[metric]);}
});
document.addEventListener('keydown',e=>{const point=e.target.closest?.('circle[data-point]');if(point&&(e.key==='Enter'||e.key===' ')){e.preventDefault();point.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{const id=e.target.id;if(['module','category','errorType','start','end'].includes(id)){const value=e.target.value;if(['start','end'].includes(id)){const start=id==='start'?value:filters.start,end=id==='end'?value:filters.end;if(!value||start>end||Date.parse(end)-Date.parse(start)>3650*DAY){notice('请选择有效的日期范围：开始日期不晚于结束日期，跨度不超过 10 年。');syncFilters();return;}$$('[data-period]').forEach(b=>b.classList.remove('selected'));}filters[id]=value;if(id==='category')filters.errorType='all';filters.status='all';page=0;syncFilters();notice('');render();}
 if(id==='compare')render();if(id==='metric'){metric=e.target.value;render();}if(id==='status'){filters.status=e.target.value;page=0;render();}if(id==='undated'){filters.includeUndated=e.target.checked;render();}
 if(id==='type-a'||id==='type-b'){if(id==='type-a')typeA=e.target.value;else typeB=e.target.value;render();}if(id==='module-a'||id==='module-b'){if(id==='module-a')moduleA=e.target.value;else moduleB=e.target.value;render();}
 if(id==='file-input')importFile(e.target.files[0]);
 if(id==='persist'){const checked=e.target.checked;(checked&&snapshot?storage('put',snapshot):storage('delete')).then(()=>{$('#storage-state').textContent=checked?'已启用此浏览器存储。可随时清除。':'默认仅在本次页面会话中使用。';}).catch(()=>{e.target.checked=false;notice('浏览器存储不可用，当前快照仍可在本次会话使用。');});}
});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){const cursor=e.target.selectionStart;filters.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=0;render();const input=$('#search');input?.focus();try{input?.setSelectionRange(cursor,cursor);}catch{}},230);}});
